package com.hms.reports;
import com.hms.appointments.*; import com.hms.audit.*; import com.hms.queue.*; import com.hms.tenancy.*; import com.hms.website.*; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/reports") public class ReportingController {private final TenantRepository tenants;private final AppointmentRepository appointments;private final PatientRepository patients;private final QueueTokenRepository tokens;private final AuditLogRepository audit;private final WebsiteContentRepository content;public ReportingController(TenantRepository t,AppointmentRepository a,PatientRepository p,QueueTokenRepository q,AuditLogRepository l,WebsiteContentRepository c){tenants=t;appointments=a;patients=p;tokens=q;audit=l;content=c;} @GetMapping("/appointments") public AppointmentSummaryDto appointments(@PathVariable String tenantSlug){UUID id=tenant(tenantSlug);List<Appointment> rows=appointments.findAllByTenantIdOrderByStartsAtAsc(id);Map<String,Long> counts=new TreeMap<>();rows.forEach(a->counts.merge(a.getStatus().name(),1L,Long::sum));return new AppointmentSummaryDto(rows.size(),counts);} @GetMapping("/queue") public Map<String,Long> queue(@PathVariable String tenantSlug){return tokens.findAllByTenantId(tenant(tenantSlug)).stream().collect(java.util.stream.Collectors.groupingBy(x->x.getStatus().name(),TreeMap::new,java.util.stream.Collectors.counting()));} @GetMapping("/audit") public List<AuditLog> audit(@PathVariable String tenantSlug){return audit.findAllByTenantIdOrderByCreatedAtDesc(tenant(tenantSlug));} @GetMapping(value="/export/appointments",produces="text/csv") public ResponseEntity<byte[]> exportAppointments(@PathVariable String tenantSlug){UUID id=tenant(tenantSlug);StringBuilder csv=new StringBuilder("id,patientId,doctorId,startsAt,endsAt,status,source,paymentStatus,reason\n");appointments.findAllByTenantIdOrderByStartsAtAsc(id).forEach(a->csv.append(row(a.getId(),a.getPatientId(),a.getDoctorId(),a.getStartsAt(),a.getEndsAt(),a.getStatus(),a.getSource(),a.getPaymentStatus(),a.getReason())));return download("appointments.csv",csv);} @GetMapping(value="/export/patients",produces="text/csv") public ResponseEntity<byte[]> exportPatients(@PathVariable String tenantSlug){StringBuilder csv=new StringBuilder("id,fullName,phone,hospitalPatientId,abhaId\n");patients.findAllByTenantId(tenant(tenantSlug)).forEach(p->csv.append(row(p.getId(),p.getFullName(),p.getPhone(),p.getHospitalPatientId(),p.getAbhaId())));return download("patients.csv",csv);} @GetMapping(value="/export/audit",produces="text/csv") public ResponseEntity<byte[]> exportAudit(@PathVariable String tenantSlug){StringBuilder csv=new StringBuilder("id,action,entityType,entityId,summary\n");audit.findAllByTenantIdOrderByCreatedAtDesc(tenant(tenantSlug)).forEach(a->csv.append(row(a.getId(),a.getAction(),a.getEntityType(),a.getEntityId(),a.getSummary())));return download("audit.csv",csv);} @GetMapping(value="/export/content",produces="text/csv") public ResponseEntity<byte[]> exportContent(@PathVariable String tenantSlug){StringBuilder csv=new StringBuilder("id,category,title,slug,status,summary,imageUrl\n");content.findAllByTenantIdOrderByUpdatedAtDesc(tenant(tenantSlug)).forEach(c->csv.append(row(c.getId(),c.getCategory(),c.getTitle(),c.getSlug(),c.getStatus(),c.getSummary(),c.getImageUrl())));return download("content.csv",csv);} private ResponseEntity<byte[]> download(String name,StringBuilder csv){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+name+"\"").contentType(MediaType.parseMediaType("text/csv")).body(csv.toString().getBytes(StandardCharsets.UTF_8));} private String row(Object... values){return Arrays.stream(values).map(v->escape(Objects.toString(v,""))).collect(java.util.stream.Collectors.joining(","))+"\n";} private String escape(String value){return "\""+value.replace("\"","\"\"").replace("\r"," ").replace("\n"," ")+"\"";} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
